ConfigScreen::ConfigScreen(TFT_eSprite &_tft, bool &_deviceConnected, StateMachine &_stateManager) : tft(&_tft), deviceConnected(&_deviceConnected), stateManager(&_stateManager)
{
  name = "ConfigScreen";
}

class State;

void ConfigScreen::enter()
{
  std::vector<String> options;
  options.push_back(String("Option 1"));
  options.push_back(String("Option 2"));
  options.push_back(String("Option 3"));

  std::vector<const uint16_t *> icons;
  icons.push_back(link_connected);
  icons.push_back(nullptr);
  icons.push_back(nullptr);

  list = new List(*tft, options, icons);
  // list_1();
  list->draw();
}

void ConfigScreen::loop() {}

void ConfigScreen::exit() {
  if (list != nullptr) {
    delete list;
    list = nullptr;
  }
}

void ConfigScreen::btnPress(String button)
{
  int selectedIndex = list->getSelectedIndex();
  Serial.println("ConfigScreen: btnPress: " + button);
  if (button == "DOWN")
  {
    if(selectedIndex < list->length() - 1) {
      Serial.println("ConfigScreen selectedIndex: " + String(selectedIndex));
      list->setSelectedIndex(selectedIndex + 1);
    }
  }
  else if (button == "UP")
  {
    if(selectedIndex > 0) {
      Serial.println("ConfigScreen selectedIndex: " + String(selectedIndex));
      list->setSelectedIndex(selectedIndex - 1);
    }
  }
}

void ConfigScreen::list_1(void)
{
  Serial.println("ConfigScreen: list_1");
  tft->fillScreen(0x0);
  tft->createSprite(240, 240);
  tft->fillSprite(TFT_BLACK);
  // rect 3
  tft->fillScreen(0x0);
  // rect 1
  tft->fillRoundRect(5, 103, 230, 35, 15, 0xBDF7);
  // string 2
  tft->setTextColor(0x4208);
  tft->setTextSize(1);
  tft->setFreeFont(&FreeSansBold12pt7b);
  tft->drawString("Connection status", 42, 113);
  // string 3
  tft->setTextColor(0xFFFF);
  tft->setFreeFont(&FreeSans9pt7b);
  tft->drawString("Disconnect device", 49, 161);
  // image-link
  tft->pushImage(208, 110, 20, 20, link_connected);
  // triangle 5
  tft->fillTriangle(120, 155, 125, 150, 115, 150, 0xBDF7);
  tft->pushSprite(0, 0);
}